require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "while admission is fenced" do
  include_context "timekeeping entry writes"

  it "refuses a create for a never-seen company with stale_generation while fenced, whatever generation header it carries" do
    company = timekeeping_arrange.company
    project = timekeeping_arrange.project(company:)
    owner = timekeeping_arrange.user(company:, role: "owner")
    token = timekeeping_arrange.token_for(owner)
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 30.0, "note" => "Fenced",
             "source" => "manual", "source_metadata" => {} }
    Timekeeping::Admission.fence!(lock_timeout: 1)
    before = entry_write_counts
    expect(before).to eq(entries: 0, audit_events: 0, outbox_snapshots: 0, idempotency_receipts: 0, versions: 0)

    # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation,
    # including for a company it has never seen"
    # An empty or non-numeric header must be refused too, never raise and never match a null generation.
    ["1", "2", "0", "", "abc"].each do |header|
      outcome = described_class.new.call(build_entry_command(:create, token:, body:, generation: header))

      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }]),
        "header #{header.inspect} was not refused"
      expect(entry_write_counts).to eq(before)
    end
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end

