# frozen_string_literal: true
require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "after re-admission" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  let(:company) { timekeeping_arrange.company }
  let(:project) { timekeeping_arrange.project(company:) }
  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }
  let(:entry_id) { timekeeping_arrange.entry(company:, user: owner, project:) }

  # "After re-admission at a generation, only that generation is accepted"
  # "After `admit!(generation: 4)`, a write carrying 4 succeeds and one carrying 3 is refused."
  it "after admit!(generation: 4) accepts a write carrying 4 and refuses writes carrying 3 or 5 with stale_generation" do
    entry_id
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    writer = described_class.new

    [3, 5].each do |generation|
      before = entry_write_counts
      refused = writer.call(build_entry_command(:update, token: owner_token, entry_id:, generation:,
                                                         body: { "note" => "Stale #{generation}" }))
      expect([refused.status, JSON.parse(refused.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(before)
    end

    admitted = writer.call(build_entry_command(:update, token: owner_token, entry_id:, generation: 4,
                                                        body: { "note" => "Admitted" }))
    expect(admitted.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Admitted")
    expect(OutboxSnapshot.where(id: entry_id).pluck(:generation)).to eq([4])
    expect(Timekeeping::Admission.current.generation).to eq(4)
  end
end

