require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::Admission, "fencing after an admitted write commits" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  let(:company) { timekeeping_arrange.company }
  let(:project) { timekeeping_arrange.project(company:) }
  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }
  let(:entry_id) { timekeeping_arrange.entry(company:, user: owner, project:) }

  # "Fencing waits for writes already admitted, with a lock timeout of 60 s in production use"
  it "fence! waits for an admitted write to commit and then leaves the generation null" do
    expect(Timekeeping::Admission::FENCE_LOCK_TIMEOUT).to eq(60.seconds)
    patch = build_entry_command(:update, token: owner_token, entry_id:, body: { "note" => "Before fence" })
    reached = Queue.new
    release = Queue.new
    checkpoint = lambda do |step|
      next unless step == :generation_checked

      reached << true
      release.pop
    end
    writer = Thread.new do
      ApplicationRecord.connection_pool.with_connection { Timekeeping::EntryWriter.new(checkpoint:).call(patch) }
    end
    expect(reached.pop(timeout: 10)).to be(true)

    fencer = Thread.new do
      ApplicationRecord.connection_pool.with_connection { Timekeeping::Admission.fence!(lock_timeout: 10) }
    end
    # The fence must still be waiting while the admitted write holds the row.
    expect(fencer.join(0.5)).to be_nil
    release << true
    outcome = writer.join(10).value
    fencer.join(10)

    expect(outcome.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Before fence")
    expect(Timekeeping::Admission.current.generation).to be_nil
  end
end
